def _median_spacing(numbers: list[tuple[int, float]]) -> float:
    if len(numbers) < 2:
        return 140.0
    gaps = [numbers[i + 1][1] - numbers[i][1] for i in range(len(numbers) - 1)]
    gaps = [gap for gap in gaps if gap > 20.0]
    if not gaps:
        return 140.0
    gaps.sort()
    return gaps[len(gaps) // 2]


def fill_missing_labels(
    labels: dict[int, tuple[int, float, float]],
    page_hits: dict[int, list[tuple[int, float, float]]],
    questions: int,
) -> dict[int, tuple[int, float, float]]:
    """Interpolate/extrapolate anchors for OCR misses between known neighbours."""
    if not labels:
        return labels

    def rail_for_page(page_index: int) -> float:
        xs = [x for number, x, _y in page_hits.get(page_index, []) if number in labels or True]
        if xs:
            clustered = _cluster_rail_x(xs)
            if clustered is not None:
                return clustered
        page_labels = [labels[n] for n in labels if labels[n][0] == page_index]
        if page_labels:
            return page_labels[0][1]
        return STRIP_LEFT + 30.0

    filled = dict(labels)
    for number in range(1, questions + 1):
        if number in filled:
            continue
        prev_n = number - 1 if number - 1 in filled else None
        next_n = number + 1 if number + 1 in filled else None
        if prev_n is not None and next_n is not None:
            p_page, p_x, p_y = filled[prev_n]
            n_page, n_x, n_y = filled[next_n]
            if p_page == n_page:
                rail = (p_x + n_x) / 2.0
                y = (p_y + n_y) / 2.0
                filled[number] = (p_page, rail, y)
                continue
        if prev_n is not None:
            page_index, x, y = filled[prev_n]
            same_page = sorted(
                [(n, yy) for n, (_p, _x, yy) in filled.items() if _p == page_index],
                key=lambda item: item[1],
            )
            spacing = _median_spacing(same_page)
            filled[number] = (page_index, x, max(y + spacing, y + 80.0))
            continue
        if next_n is not None:
            page_index, x, y = filled[next_n]
            same_page = sorted(
                [(n, yy) for n, (_p, _x, yy) in filled.items() if _p == page_index],
                key=lambda item: item[1],
            )
            spacing = _median_spacing(same_page)
            filled[number] = (page_index, x, max(20.0, y - spacing))

    return filled

